SELECT e1.name AS Employee, e2.name AS Manager
FROM employees e1
INNER JOIN employees e2 ON e1.manager_id = e2.id;

WITH cte AS (
  SELECT dept_id, COUNT(*) AS emp_count
  FROM employees
  GROUP BY dept_id
)
SELECT * FROM cte WHERE emp_count > 5;

SELECT e.name
FROM employees e
WHERE e.salary > ALL (SELECT salary FROM employees WHERE dept = 'IT');

SELECT DISTINCT customer_id
FROM orders
WHERE customer_id NOT IN (SELECT customer_id FROM returns);

WITH RECURSIVE nums AS (
  SELECT 1 AS n
  UNION ALL
  SELECT n + 1 FROM nums WHERE n < 5
)
SELECT * FROM nums;

WITH sales_cte AS (
  SELECT salesperson, SUM(amount) AS total
  FROM orders
  GROUP BY salesperson
)
SELECT salesperson FROM sales_cte WHERE total > 10000;

SELECT DISTINCT a.customer_id
FROM orders a
WHERE EXISTS (SELECT 1 FROM orders b WHERE a.customer_id = b.customer_id AND a.order_date <> b.order_date);

SELECT e.name
FROM employees e
WHERE e.salary > ANY (SELECT salary FROM employees WHERE dept = 'Sales');

SELECT a.name AS employee, b.name AS colleague
FROM employees a
INNER JOIN employees b ON a.dept_id = b.dept_id AND a.id <> b.id;

SELECT e1.name AS employee, COALESCE(e2.name, 'Top Manager') AS manager
FROM employees e1
LEFT JOIN employees e2 ON e1.manager_id = e2.id;

SELECT e.name, e.salary
FROM employees e
WHERE e.salary > (SELECT AVG(salary) FROM employees WHERE dept_id = e.dept_id);

SELECT DISTINCT o.customer_id
FROM orders o
WHERE NOT EXISTS (
  SELECT 1 FROM returns r WHERE r.order_id = o.id
);

SELECT table1.*, table2.*
FROM table1
NATURAL FULL OUTER JOIN table2;

SELECT name
FROM employees e1
WHERE salary = (
  SELECT MAX(salary) FROM employees e2 WHERE e2.dept_id = e1.dept_id
);

SELECT a.customer_name, b.customer_name
FROM customers a
INNER JOIN customers b ON a.city = b.city AND a.id < b.id;

SELECT e.name, e.salary
FROM employees e
WHERE e.salary >= ALL (SELECT salary FROM employees WHERE dept_id = e.dept_id);

SELECT e.name, e.salary
FROM employees e
WHERE e.salary > (
  SELECT MAX(salary) FROM employees WHERE dept_id = e.dept_id AND title = 'Junior'
);

SELECT name FROM employees e1
WHERE NOT EXISTS (
  SELECT 1 FROM employees e2 WHERE e2.manager_id = e1.id
);

SELECT e1.name, e2.name AS manager
FROM Employees [0]
LEFT JOIN Employees [1] ON e1.manager_id = e2.id;

SELECT name
FROM products p
WHERE price > ALL (
  SELECT price FROM products WHERE category = p.category AND id != p.id
);

SELECT customer_id FROM orders
INTERSECT
SELECT customer_id FROM returns;

WITH RECURSIVE counter AS (
  SELECT 1 AS val
  UNION ALL
  SELECT val + 1 FROM counter WHERE val < 5
)
SELECT SUM(val) FROM counter;

SELECT dept_id, MIN(salary)
FROM employees
GROUP BY dept_id
HAVING MIN(salary) > (
  SELECT MIN(salary) FROM employees WHERE dept_id = 1
);

WITH cte1 AS (
  SELECT id, name FROM departments WHERE active = 1
),
cte2 AS (
  SELECT e.name, e.dept_id FROM employees e INNER JOIN cte1 ON e.dept_id = cte1.id
)
SELECT * FROM cte2;

SELECT e.name
FROM employees e
WHERE e.salary > (
  SELECT PERCENTILE_CONT(0.9) WITHIN GROUP (ORDER BY salary)
  FROM employees WHERE dept_id = e.dept_id
);

SELECT a.name
FROM employees a
WHERE NOT EXISTS (
  SELECT 1 FROM employees b
  WHERE b.manager_id = a.id
)
AND EXISTS (
  SELECT 1 FROM employees c WHERE c.dept_id = a.dept_id AND c.id <> a.id
);

SELECT d.name
FROM departments d
WHERE d.id IN (
  SELECT dept_id FROM employees GROUP BY dept_id
  HAVING COUNT(*) > ALL (
    SELECT AVG(cnt) FROM (
      SELECT COUNT(*) AS cnt FROM employees GROUP BY dept_id
    ) AS sub
  )
);

SELECT name
FROM employees e
WHERE (
  SELECT COUNT(*) FROM employees sub
  WHERE sub.dept_id = e.dept_id AND sub.salary > e.salary
) < 3;

WITH dept_ranks AS (
  SELECT dept_id, salary,
    DENSE_RANK() OVER (PARTITION BY dept_id ORDER BY salary DESC) AS dr
  FROM employees
)
SELECT DISTINCT dept_id, salary FROM dept_ranks WHERE dr <= 2;

SELECT name FROM employees e
WHERE EXISTS (
  SELECT 1 FROM employees sub
  WHERE sub.manager_id = e.id
  HAVING COUNT(*) > 5
);

SELECT e.name
FROM employees e
WHERE (
  SELECT COUNT(*) FROM employees sub
  WHERE sub.dept_id = e.dept_id AND sub.hire_date < e.hire_date
) = 2;

SELECT d.name
FROM departments d
WHERE EXISTS (
  SELECT 1 FROM employees e
  WHERE e.dept_id = d.id
  GROUP BY e.dept_id
  HAVING COUNT(DISTINCT e.title) >= ALL (
    SELECT COUNT(DISTINCT title) FROM employees GROUP BY dept_id
  )
);
